BEGIN TRANSACTION;
CREATE TABLE "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE "auth_user" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "last_name" varchar(150) NOT NULL, "email" varchar(254) NOT NULL, "is_staff" bool NOT NULL, "is_active" bool NOT NULL, "date_joined" datetime NOT NULL, "first_name" varchar(150) NOT NULL);
CREATE TABLE "auth_user_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_user_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "action_time" datetime NOT NULL);
CREATE TABLE "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE "django_migrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" datetime NOT NULL);
CREATE TABLE "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
CREATE TABLE "inventory_computertype" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "type_code" varchar(20) NOT NULL UNIQUE, "type_name" varchar(100) NOT NULL, "category" varchar(20) NOT NULL, "brand" varchar(50) NOT NULL, "model" varchar(100) NOT NULL, "specs" text NOT NULL, "warranty_months" integer NOT NULL, "description" text NOT NULL);
CREATE TABLE "inventory_department" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "code" varchar(50) NOT NULL UNIQUE, "name" varchar(50) NOT NULL, "description" text NOT NULL, "sort_order" integer NOT NULL, "is_active" bool NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "parent_id" bigint NULL REFERENCES "inventory_department" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "inventory_itdevice" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "device_no" varchar(50) NOT NULL UNIQUE, "asset_no" varchar(50) NOT NULL, "serial_no" varchar(100) NOT NULL, "purchase_date" date NULL, "price" decimal NOT NULL, "location" varchar(100) NOT NULL, "user" varchar(100) NOT NULL, "status" varchar(20) NOT NULL, "remarks" text NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "department_id" bigint NULL REFERENCES "inventory_department" ("id") DEFERRABLE INITIALLY DEFERRED, "device_type_id" bigint NOT NULL REFERENCES "inventory_computertype" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "inventory_itemcategory" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "code" varchar(20) NOT NULL UNIQUE, "name" varchar(50) NOT NULL, "description" text NOT NULL, "sort_order" integer NOT NULL, "is_active" bool NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "parent_id" bigint NULL REFERENCES "inventory_itemcategory" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "inventory_officesupply" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "code" varchar(50) NOT NULL UNIQUE, "name" varchar(100) NOT NULL, "specification" varchar(100) NOT NULL, "unit" varchar(20) NOT NULL, "quantity" integer NOT NULL, "locked_quantity" integer NOT NULL, "safety_stock" integer NOT NULL, "location" varchar(100) NOT NULL, "supplier" varchar(100) NOT NULL, "price" decimal NOT NULL, "status" varchar(20) NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "item_category_id" bigint NULL REFERENCES "inventory_itemcategory" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "inventory_profile" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(50) NOT NULL, "phone" varchar(20) NOT NULL, "applied_role" varchar(20) NOT NULL, "is_pending" bool NOT NULL, "department_id" bigint NULL REFERENCES "inventory_department" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NOT NULL UNIQUE REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "inventory_returnapplication" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "return_no" varchar(50) NOT NULL UNIQUE, "quantity" integer NOT NULL, "returner" varchar(100) NOT NULL, "return_date" date NOT NULL, "reason" text NOT NULL, "status" varchar(20) NOT NULL, "approval_time" datetime NULL, "approval_comment" text NOT NULL, "created_at" datetime NOT NULL, "specification" varchar(100) NOT NULL, "unit" varchar(20) NOT NULL, "location" varchar(100) NOT NULL, "supplier" varchar(100) NOT NULL, "approver_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "department_id" bigint NULL REFERENCES "inventory_department" ("id") DEFERRABLE INITIALLY DEFERRED, "operator_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "supply_id" bigint NOT NULL REFERENCES "inventory_officesupply" ("id") DEFERRABLE INITIALLY DEFERRED, "stockout_order_id" bigint NULL REFERENCES "inventory_stockoutorder" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "inventory_rolepermission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "module" varchar(30) NOT NULL, "action" varchar(20) NOT NULL, "scope" varchar(20) NOT NULL, "is_enabled" bool NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "role_id" bigint NOT NULL REFERENCES "inventory_systemrole" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "inventory_stockinapplication" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "application_no" varchar(50) NOT NULL UNIQUE, "reason" text NOT NULL, "stockin_date" date NOT NULL, "status" varchar(20) NOT NULL, "approval_time" datetime NULL, "approval_comment" text NOT NULL, "created_at" datetime NOT NULL, "applicant_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "approver_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "department_id" bigint NULL REFERENCES "inventory_department" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "inventory_stockinitem" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "quantity" integer NOT NULL, "unit_price" decimal NOT NULL, "specification" varchar(100) NOT NULL, "unit" varchar(20) NOT NULL, "location" varchar(100) NOT NULL, "supplier" varchar(100) NOT NULL, "application_id" bigint NOT NULL REFERENCES "inventory_stockinapplication" ("id") DEFERRABLE INITIALLY DEFERRED, "supply_id" bigint NOT NULL REFERENCES "inventory_officesupply" ("id") DEFERRABLE INITIALLY DEFERRED, "doc_no" varchar(100) NOT NULL);
CREATE TABLE "inventory_stockoutitem" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "quantity" integer NOT NULL, "specification" varchar(100) NOT NULL, "unit" varchar(20) NOT NULL, "location" varchar(100) NOT NULL, "supplier" varchar(100) NOT NULL, "supply_id" bigint NOT NULL REFERENCES "inventory_officesupply" ("id") DEFERRABLE INITIALLY DEFERRED, "order_id" bigint NOT NULL REFERENCES "inventory_stockoutorder" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "inventory_stockoutorder" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "record_no" varchar(50) NOT NULL UNIQUE, "recipient" varchar(100) NOT NULL, "purpose" text NOT NULL, "out_type" varchar(20) NOT NULL, "status" varchar(20) NOT NULL, "dept_approval_time" datetime NULL, "dept_approval_comment" text NOT NULL, "approval_time" datetime NULL, "approval_comment" text NOT NULL, "created_at" datetime NOT NULL, "approver_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "department_id" bigint NULL REFERENCES "inventory_department" ("id") DEFERRABLE INITIALLY DEFERRED, "dept_approver_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "operator_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "inventory_supplycategory" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "code" varchar(20) NOT NULL UNIQUE, "name" varchar(50) NOT NULL UNIQUE, "description" text NOT NULL, "sort_order" integer NOT NULL, "created_at" datetime NOT NULL);
CREATE TABLE "inventory_systemrole" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "key" varchar(20) NOT NULL UNIQUE, "name" varchar(50) NOT NULL, "description" text NOT NULL, "is_builtin" bool NOT NULL, "is_active" bool NOT NULL, "sort_order" integer NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL);
CREATE UNIQUE INDEX "auth_group_permissions_group_id_permission_id_0cd325b0_uniq" ON "auth_group_permissions" ("group_id", "permission_id");
CREATE INDEX "auth_group_permissions_group_id_b120cbf9" ON "auth_group_permissions" ("group_id");
